import GroupedDataInteraction from '../grouped-data-interaction/grouped-data-interaction';
import InteractionHelper from '../helpers/interaction/interaction';
import StatementVerbHelper from '../helpers/statement/verb';
import { IGroupedDataUser } from '../interfaces/IGroupedDataUser';
import InverseFunctionalIdentifier from '../inverse-functional-identifier/inverse-functional-identifier';
import { Attempt } from '../types/attempt';
import { EXTENSION_URL_TRACKING_STATE } from '../types/extension';
import { Statement } from '../types/statement';
import { XTScoreMode } from '../types/xt-score-mode';
import XTResults from '../xt-results/xt-results';

export default class GroupedDataUser implements IGroupedDataUser {
  /** A list of attempt keys */
  public get attemptKeys(): string[] {
    return this.#attemptKeys;
  }

  /** A list of attempts */
  public get attempts(): Attempt[] {
    return this.#attempts;
  }

  /** An InverseFunctionalIdentifier */
  public get ifi(): InverseFunctionalIdentifier {
    return this.#ifi;
  }

  /** A list of interactions */
  public get interactions(): GroupedDataInteraction[] {
    return this.#interactions;
  }

  /** A list of statementIdxs */
  public get statementIdxs(): number[] {
    return this.#statementIdxs;
  }

  /** A list of usedAttempts */
  public get usedAttempts(): string[] {
    return this.#usedAttempts;
  }

  /** The number of attempts */
  public get nrAttempts(): number {
    return this.#attempts.length;
  }

  #attemptKeys: string[] = [];

  #attempts: Attempt[] = [];

  #ifi: InverseFunctionalIdentifier;

  #interactions: GroupedDataInteraction[];

  #statementIdxs: number[] = [];

  #usedAttempts: string[] = [];

  #userIndex: number;

  public constructor(
    { ifi, userIndex, interactions }:
    { ifi: InverseFunctionalIdentifier; userIndex: number, interactions: GroupedDataInteraction[] },
  ) {
    this.#ifi = ifi;
    this.#userIndex = userIndex;
    // Clone the interactions
    this.#interactions = interactions.map((interaction) => interaction.deepCopy());
  }

  /**
   * Add an attempt to the user
   *
   * @param attemptKey - The key of the attempt
   * @param statementIdx - The index of the statement
   * @param [interaction] - The interaction
   */
  public addAttempt({ attemptKey, statementIdx, interaction }:
  { attemptKey: string; statementIdx: number; interaction?: GroupedDataInteraction }): void {
    let userAttempt = this.#attempts.find(
      (attempt) => attempt.key === attemptKey,
    );
    if (userAttempt === undefined) {
      userAttempt = { key: attemptKey, statementIdxs: [] };
      this.#attempts.push(userAttempt);
      this.#attemptKeys.push(attemptKey);
    }
    userAttempt.statementIdxs.push(statementIdx);

    this.#statementIdxs.push(statementIdx);
  }

  /**
   * Prepare the statistics for the user
   *
   * @param statements - A list of statements
   * @param scoreMode - The score mode
   */
  public prepareStatistics(
    {
      statements, interactionHashes, scoreMode,
    }:
    {
      statements: Statement[];
      interactionHashes: Map<string, { index: number; childIndex: number | undefined }>;
      scoreMode: XTScoreMode
    },
  ): void {
    this.#attempts = this.#attempts.map((attempt) => {
      const attemptStatements = attempt.statementIdxs.map((idx) => statements[idx]);
      // Find the exit statements
      const statementsWithResult = StatementVerbHelper.getStatementsWithResultExtension(
        attemptStatements,
      );
      if (statementsWithResult.length > 0) {
        // Load the most recent result (statements are coming in reverse order)
        const usedStatement = statementsWithResult[0];

        if (usedStatement.result?.extensions[EXTENSION_URL_TRACKING_STATE] !== undefined) {
          const xtResults = new XTResults(usedStatement);
          console.log(xtResults);

          return {
            completedPercentage: xtResults.completion,
            completedStatus: xtResults.completedStatus,
            duration: xtResults.totalDuration,
            key: attempt.key,
            score: Math.round(xtResults.averageScore * xtResults.completion) / 100,
            start: usedStatement.timestamp,
            statementIdxs: attempt.statementIdxs,
            successStatus: xtResults.successStatus,
          };
        }

        return {
          completedPercentage: 0,
          completedStatus: 'unknown',
          key: attempt.key,
          score: usedStatement.result?.score?.raw ?? 0,
          start: usedStatement.timestamp,
          statementIdxs: attempt.statementIdxs,
          successStatus: 'unknown',
        };
      }
      // No exited statements found, get the first and last statement
      return {
        completedPercentage: 0,
        completedStatus: 'unknown',
        end: statements[attempt.statementIdxs[attempt.statementIdxs.length - 1]].timestamp,
        key: attempt.key,
        score: 0,
        start: statements[attempt.statementIdxs[0]].timestamp,
        statementIdxs: attempt.statementIdxs,
        successStatus: 'unknown',
      };
    });

    // TODO: make sure only the used attempt is used here
    this.#interactions.forEach((interaction) => {
      // Update the interaction
      interaction.updateInteraction(this.#statementIdxs, statements);

      // Update the sub-interactions
      interaction.subInteractions.forEach((subInteraction) => {
        subInteraction.updateInteraction(this.#statementIdxs, statements);
      });
    });
  }
}
