import { Duration } from 'luxon';

import StatementInteractionHelper from '../helpers/interaction/statement-interaction';
import StatementVerbHelper from '../helpers/statement/verb';
import { IGroupedDataInteraction } from '../interfaces/IGroupedDataInteraction';
import { CompletedStatus } from '../types/completed-status';
import {
  EXTENSION_URL_SESSION_ID,
  EXTENSION_URL_VIDEO_LENGTH,
  EXTENSION_URL_VIDEO_TIME,
} from '../types/extension';
import { InteractionAnswer } from '../types/interactionAnswers';
import { Statement } from '../types/statement';
import { SuccessStatus } from '../types/success-status';
import { VERB_URL_VIDEO_PAUSED, VERB_URL_VIDEO_PLAYED } from '../types/verb';

export default class GroupedDataInteraction implements IGroupedDataInteraction {
  /** The completedStatus of the interaction */
  public get completedStatus(): CompletedStatus | undefined {
    return this.#completedStatus;
  }

  /** The key of the interaction */
  public get key(): number {
    return this.#key;
  }

  /** The key of the module */
  public get module(): number | undefined {
    return this.#module;
  }

  /** The name of the interaction */
  public get name(): string {
    return this.#name;
  }

  /** A list of statement indexes */
  public get statementIdxs(): number[] {
    return this.#statementIdxs;
  }

  /** A list of sub interactions */
  public get subInteractions(): GroupedDataInteraction[] {
    return this.#subInteractions;
  }

  /** The successStatus of the interaction */
  public get successStatus(): SuccessStatus | undefined {
    return this.#successStatus;
  }

  /** The url of the interaction */
  public get url(): string {
    return this.#url;
  }

  #completedStatus: CompletedStatus | undefined;

  #key: number;

  #module: number | undefined;

  #name: string;

  #statementIdxs: number[];

  #subInteractions: GroupedDataInteraction[];

  #successStatus: SuccessStatus | undefined;

  #url: string;

  /**
   * Constructor for GroupedDataInteraction
   *
   * @param [completedStatus] - The completedStatus of the interaction
   * @param key - The key of the interaction
   * @param [module] - The key of the module
   * @param name - The name of the interaction
   * @param statementIdxs - A list of statement indexes
   * @param [subInteractions] - The sub-interactions of the interaction
   * @param [successStatus] - The successStatus of the interaction
   * @param url - The url of the interaction
   */
  constructor({
    completedStatus, key, module, name, statementIdxs, subInteractions, successStatus,
    url,
  }: {
    completedStatus?: CompletedStatus;
    key: number;
    module?: number;
    name: string;
    statementIdxs: number[];
    subInteractions?: GroupedDataInteraction[];
    successStatus?: SuccessStatus;
    url: string;
  }) {
    this.#completedStatus = completedStatus;
    this.#key = key;
    this.#module = module;
    this.#name = name;
    this.#statementIdxs = statementIdxs;
    this.#subInteractions = subInteractions ?? [];
    this.#successStatus = successStatus;
    this.#url = url;
  }

  /**
   * Deep copy of the GroupedDataInteraction
   *
   * @returns A new GroupedDataInteraction object copied by value instead of reference
   */
  public deepCopy(): GroupedDataInteraction {
    const subInteractions = this.#subInteractions.map((interaction) => interaction.deepCopy());
    return new GroupedDataInteraction({
      completedStatus: this.#completedStatus,
      key: this.#key,
      module: this.#module,
      name: this.#name,
      statementIdxs: this.#statementIdxs,
      subInteractions,
      successStatus: this.#successStatus,
      url: this.#url,
    });
  }

  /**
   * Add statement indexes to the interaction
   *
   * @param statementId - The statement index to add
   */
  public addStatement(statementId: number) {
    this.#statementIdxs.push(statementId);
  }

  /**
   * Sets the statement indexes to the interaction, this overrites the current statement indexes
   *
   * @param statementIdxs - An array of statement indexes
   */
  public setStatementIdxs(statementIdxs: number[]) {
    this.#statementIdxs = statementIdxs;
  }

  /**
   * Add sub interactions to the interaction
   *
   * @param interaction - A GroupedDataInteraction object
   */
  public addSubInteraction(interaction: GroupedDataInteraction) {
    this.#subInteractions.push(interaction);
  }

  /**
   * Get the score of the statements from the interaction
   *
   * @param statements - A list of Statement objects
   * @returns The score of the interaction
   */
  public getScore(statements: Statement[]): number {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    return StatementVerbHelper.getStatementsWithScoreExtension(usedStatements).map(
      (statement) => statement.result?.score?.scaled ?? 0,
    )[0]; // TODO: This returns the last score. This should become configurable
  }

  /**
  * Get the scored statements from the interaction
   *
   * @param statements - A list of Statement objects
   * @param pick - Whether to pick the 'first' or 'last' statement from each session group
   * @returns The scored statements from the interaction, deduplicated per sessionId
   */
  public getScoredStatements(statements: Statement[], pick: 'first' | 'last' = 'last'): Statement[] {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    const scoredStatements = StatementVerbHelper.getStatementsWithScoreExtension(usedStatements);
    return GroupedDataInteraction.groupStatementsBySessionId(scoredStatements, pick);
  }

  /**
   * Groups statements by sessionId and returns the first or last statement from each group.
   * Statements without a sessionId cannot be grouped and are returned individually.
   *
   * @param statements - A list of Statement objects
   * @param pick - Whether to pick the 'first' or 'last' statement from each session group
   * @returns One statement per sessionId group, plus all session-less statements
   */
  private static groupStatementsBySessionId(statements: Statement[], pick: 'first' | 'last'): Statement[] {
    const groups = new Map<string, Statement>();
    const ungrouped: Statement[] = [];

    statements.forEach((statement) => {
      const sessionId = statement.context?.extensions[EXTENSION_URL_SESSION_ID];
      if (sessionId === undefined) {
        ungrouped.push(statement);
        return;
      }
      if (pick === 'last' || !groups.has(sessionId)) {
        groups.set(sessionId, statement);
      }
    });

    return [...Array.from(groups.values()), ...ungrouped];
  }

  /**
   * Get the answered statements from the interaction
   *
   * @param statements - A list of Statement objects
   * @param pick - Whether to pick the 'first' or 'last' statement from each session group
   * @returns The answered statements from the interaction, deduplicated per sessionId
   */
  public getAnsweredStatements(statements: Statement[], pick: 'first' | 'last' = 'last'): Statement[] {
    const statementIdxs = [
      ...this.#statementIdxs,
      ...this.#subInteractions.flatMap((subInteraction) => subInteraction.#statementIdxs),
    ];
    const usedStatements = statementIdxs.map((statementId) => statements[statementId]);
    const answeredStatements = StatementVerbHelper.getStatementsByAnsweredVerb(usedStatements);
    return GroupedDataInteraction.groupStatementsBySessionId(answeredStatements, pick);
  }

  /**
   * Get the initializations from the interaction
   *
   * @param statements - A list of Statement objects
   * @returns The number of initializations
   */
  public getInitializations(statements: Statement[]): number {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    return StatementVerbHelper.getStatementsByInitializedVerb(usedStatements).length;
  }

  /**
   * Get the duration from the interaction
   *
   * @param statements - A list of Statement objects
   * @returns The duration of the interaction
   */
  public getDuration(statements: Statement[]): number {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    const scoredStatements = StatementVerbHelper.getStatementsWithScoreExtension(usedStatements);

    return scoredStatements.map(
      (statement) => Duration.fromISO(statement.result?.duration ?? '').as('seconds'),
    )[0]; // TODO: This returns the last duration. This should become configurable;
  }

  /**
   * Get the answer options from the interaction
   *
   * Detects the interaction type from the first answered statement and delegates
   * to the appropriate private static builder method. For 'text' and related
   * open-response types, all answered statements are used without session
   * deduplication since each individual submission is meaningful.
   *
   * @param statements - A list of Statement objects
   * @param pick - Whether to pick the 'first' or 'last' statement from each session group
   * @returns The answer options from the interaction, aggregated over deduplicated sessions
   */
  public getInteractionAnswerOptions(statements: Statement[], pick: 'first' | 'last' = 'first'): InteractionAnswer {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);
    const answeredStatements = GroupedDataInteraction.groupStatementsBySessionId(
      StatementVerbHelper.getStatementsByAnsweredVerb(usedStatements),
      pick,
    );

    let interactionType = answeredStatements[0]?.object?.definition?.interactionType;

    // Fallback: some Xerte text (model-answer) interactions set interactionType other
    // on the statement. When the description starts with modes, make interactionType
    // text
    if (interactionType === 'other') {
      const description = answeredStatements[0]?.object?.definition?.description;
      if (
        description !== undefined
        && Object.values(description).some((v) => v.includes('Model'))
      ) {
        interactionType = 'text';
      }
    }

    switch (interactionType) {
      case 'matching':
      case 'match':
        return GroupedDataInteraction.buildMatchingAnswer(answeredStatements);
      case 'fill-in':
      case 'long-fill-in':
        return GroupedDataInteraction.buildFillInAnswer(answeredStatements);
      case 'numeric':
        return GroupedDataInteraction.buildNumericAnswer(answeredStatements);
      case 'text':
      case 'other':
      case 'performance':
      case 'likert':
      case 'true-false': {
        return GroupedDataInteraction.buildTextAnswer(answeredStatements);
      }
      case 'choice':
      case 'multiplechoice':
      case 'sequencing':
      default:
        return GroupedDataInteraction.buildChoicesAnswer(answeredStatements);
    }
  }

  /**
   * Get video answer options from statements
   *
   * Uses paused and played verbs (not the answered verb) to derive pause events,
   * duration blocks, video duration, and the number of unique learners.
   *
   * @param statements - A list of Statement objects
   * @returns A VideoAnswer wrapped in an InteractionAnswer discriminated union
   */
  public getVideoAnswerOptions(statements: Statement[]): InteractionAnswer {
    const usedStatements = this.#statementIdxs.map((statementId) => statements[statementId]);

    const pausedStatements = usedStatements.filter(
      (s) => s.verb.id === VERB_URL_VIDEO_PAUSED,
    );
    const playedStatements = usedStatements.filter(
      (s) => s.verb.id === VERB_URL_VIDEO_PLAYED,
    );

    const pauseEvents = pausedStatements.map((s) => ({
      position: Number(s.result?.extensions?.[EXTENSION_URL_VIDEO_TIME] ?? 0),
      timestamp: s.stored ?? s.timestamp ?? '',
    }));

    const actorKey = (s: Statement): string => s.actor.mbox ?? s.actor.account?.name ?? 'unknown';

    const playByActor = new Map<string, Statement[]>();
    playedStatements.forEach((s) => {
      const key = actorKey(s);
      if (!playByActor.has(key)) {
        playByActor.set(key, []);
      }
      playByActor.get(key)!.push(s);
    });

    // Pre-sort each actor's play events in descending stored-timestamp order so that
    // each pause lookup can use a single O(n) .find() instead of an O(n log n) sort.
    playByActor.forEach((plays) => {
      plays.sort((a, b) => b.stored.localeCompare(a.stored));
    });

    const durationBlocks: Array<{ start: number; end: number }> = [];
    pausedStatements.forEach((pauseStmt) => {
      const key = actorKey(pauseStmt);
      const pauseTime = Number(pauseStmt.result?.extensions?.[EXTENSION_URL_VIDEO_TIME] ?? 0);
      const actorPlays = playByActor.get(key) ?? [];
      const precedingPlay = actorPlays.find((p) => p.stored <= pauseStmt.stored);
      if (precedingPlay !== undefined) {
        const startTime = Number(precedingPlay.result?.extensions?.[EXTENSION_URL_VIDEO_TIME] ?? 0);
        durationBlocks.push({ start: startTime, end: pauseTime });
      }
    });

    const videoDuration = (() => {
      const raw = usedStatements
        .map((s) => s.result?.extensions?.[EXTENSION_URL_VIDEO_LENGTH])
        .find((v) => v !== undefined);
      return raw !== undefined ? Number(raw) : undefined;
    })();

    const nrOfLearners = new Set(
      [...pausedStatements, ...playedStatements].map(actorKey),
    ).size;

    return {
      type: 'video',
      answer: {
        pauseEvents,
        durationBlocks,
        videoDuration,
        nrOfLearners,
      },
    };
  }

  private static buildChoicesAnswer(answeredStatements: Statement[]): InteractionAnswer {
    return {
      type: 'choices',
      answer: {
        choices: Array.from(new Set(
          answeredStatements.flatMap(
            (statement) => statement.object?.definition?.choices?.map((choice) => choice.id) ?? [],
          ),
        )),
        choicesResponse: answeredStatements.flatMap(
          (statement) => statement.result?.response?.split('[,]'),
        ).reduce(
          (acc, response) => acc.set(
            response,
            (acc.get(response) || 0) + 1,
          ),
          new Map<string | undefined, number>(),
        ),
        correctResponsesPattern: answeredStatements.flatMap(
          (statement) => statement.object?.definition?.correctResponsesPattern?.flatMap(
            (responsePattern) => responsePattern.split('[,]'),
          ) ?? [],
        ),
        nrOfAttempts: answeredStatements.length,
      },
    };
  }

  private static buildMatchingAnswer(answeredStatements: Statement[]): InteractionAnswer {
    const sources = Array.from(new Set(
      answeredStatements.flatMap(
        (s) => s.object?.definition?.source?.map((item) => item.id) ?? [],
      ),
    ));
    const targets = Array.from(new Set(
      answeredStatements.flatMap(
        (s) => s.object?.definition?.target?.map((item) => item.id) ?? [],
      ),
    ));

    const correctPairs = new Map<string, string>();
    const firstWithPatterns = answeredStatements.find(
      (s) => (s.object?.definition?.correctResponsesPattern ?? []).length > 0,
    );
    if (firstWithPatterns) {
      (firstWithPatterns.object?.definition?.correctResponsesPattern ?? []).forEach((pattern) => {
        pattern.split('[,]').forEach((pair) => {
          const [src, tgt] = pair.split('[.]');
          if (src !== undefined && tgt !== undefined) {
            correctPairs.set(src, tgt);
          }
        });
      });
    }

    const pairsResponse = new Map<string, number>();
    answeredStatements.forEach((s) => {
      const response = s.result?.response;
      if (!response) return;
      response.split('[,]').forEach((pair) => {
        pairsResponse.set(pair, (pairsResponse.get(pair) || 0) + 1);
      });
    });

    return {
      type: 'matching',
      answer: {
        sources,
        targets,
        correctPairs,
        pairsResponse,
        nrOfAttempts: answeredStatements.length,
      },
    };
  }

  private static buildFillInAnswer(answeredStatements: Statement[]): InteractionAnswer {
    const correctResponsesPattern = Array.from(new Set(
      answeredStatements.flatMap(
        (s) => s.object?.definition?.correctResponsesPattern ?? [],
      ),
    ));

    const responsesMap = new Map<string, number>();
    answeredStatements.forEach((s) => {
      const response = s.result?.response ?? '';
      responsesMap.set(response, (responsesMap.get(response) || 0) + 1);
    });

    const responses = Array.from(responsesMap.entries())
      .sort(([, a], [, b]) => b - a)
      .map(([response]) => response);

    return {
      type: 'fill-in',
      answer: {
        correctResponsesPattern,
        responsesMap,
        responses,
        nrOfAttempts: answeredStatements.length,
      },
    };
  }

  private static buildTextAnswer(answeredStatements: Statement[]): InteractionAnswer {
    const responses = answeredStatements.map((s) => ({
      response: s.result?.response ?? '',
      timestamp: s.stored ?? s.timestamp ?? '',
    }));

    return {
      type: 'text',
      answer: {
        responses,
        nrOfAttempts: answeredStatements.length,
      },
    };
  }

  private static buildNumericAnswer(answeredStatements: Statement[]): InteractionAnswer {
    const correctResponsesPattern = answeredStatements.flatMap(
      (s) => s.object?.definition?.correctResponsesPattern ?? [],
    );

    const parsedResponses = answeredStatements
      .map((s) => parseFloat(s.result?.response ?? ''))
      .filter((n) => !Number.isNaN(n) && Number.isFinite(n));

    const sorted = [...parsedResponses].sort((a, b) => a - b);

    const min = sorted.length > 0 ? sorted[0] : undefined;
    const max = sorted.length > 0 ? sorted[sorted.length - 1] : undefined;
    const mean = sorted.length > 0
      ? sorted.reduce((acc, n) => acc + n, 0) / sorted.length
      : undefined;
    let median: number | undefined;
    if (sorted.length > 0) {
      if (sorted.length % 2 === 1) {
        median = sorted[Math.floor(sorted.length / 2)];
      } else {
        median = (sorted[sorted.length / 2 - 1]! + sorted[sorted.length / 2]!) / 2;
      }
    }

    const isCorrect = (n: number): boolean => {
      if (correctResponsesPattern.length === 0) return false;
      return correctResponsesPattern.some((pattern) => {
        if (pattern.includes(':')) {
          const [minPart, maxPart] = pattern.split(':');
          const rawMin = minPart !== '' ? parseFloat(minPart) : -Infinity;
          const rawMax = maxPart !== '' ? parseFloat(maxPart) : Infinity;
          return !Number.isNaN(rawMin) && !Number.isNaN(rawMax) && n >= rawMin && n <= rawMax;
        }
        const exact = parseFloat(pattern);
        return !Number.isNaN(exact) && n === exact;
      });
    };

    const correctCount = parsedResponses.filter(isCorrect).length;

    return {
      type: 'numeric',
      answer: {
        correctResponsesPattern,
        responses: parsedResponses,
        min,
        max,
        mean,
        median,
        correctCount,
        nrOfAttempts: answeredStatements.length,
      },
    };
  }

  /**
    * Update the interaction with new statement indexes and set the completion status
    *
    * @param allStatementIdxs - A list of all statement indexes
    * @param statements - A list of Statement objects
    */
  public updateInteraction(
    allStatementIdxs: number[],
    statements: Statement[],
  ) {
    // Filter the statementIdxs — use a Set for O(1) membership checks
    const allStatementIdxSet = new Set(allStatementIdxs);
    const statementIdxs = this.#statementIdxs.filter(
      (statementId) => allStatementIdxSet.has(statementId),
    );
    this.setStatementIdxs(statementIdxs);

    // Set the completion status
    const hasPassed = StatementInteractionHelper.hasPassed({ statements, statementIdxs });
    const hasCompleted = StatementInteractionHelper.hasCompleted({ statements, statementIdxs });
    const hasStarted = StatementInteractionHelper.hasStarted({ statements, statementIdxs });

    this.setCompletedStatus({ hasPassed, hasCompleted, hasStarted });
  }

  /**
     * Sets the completed status and the succes status of the interaction
     *
     * @param hasPassed - A boolean indicating if the interaction has passed
     * @param hasCompleted - A boolean indicating if the interaction has been completed
     * @param hasStarted - A boolean indicating if the interaction has been started
     */
  private setCompletedStatus({ hasPassed, hasCompleted, hasStarted }: {
    hasPassed: boolean;
    hasCompleted: boolean;
    hasStarted: boolean;
  }) {
    if (hasPassed) {
      this.#completedStatus = 'completed';
      this.#successStatus = 'passed';
    } else if (hasCompleted) {
      this.#completedStatus = 'completed';
      this.#successStatus = 'failed';
    } else if (hasStarted) {
      this.#completedStatus = 'incomplete';
    }
  }
}
