import GroupedDataInteraction from '../../grouped-data-interaction/grouped-data-interaction';
import GroupedDataUser from '../../grouped-data-user/grouped-data-user';
import InverseFunctionalIdentifier from '../../inverse-functional-identifier/inverse-functional-identifier';
import { Statement } from '../../types/statement';
import { User } from '../../types/user';
import { getInverseFunctionalIdentifier } from '../statement/statement';

export default class UserHelper {
/**
 * Creates GroupedDataUser objects from User objects
 *
 * @param users - A list of User objects
 * @returns A set of GroupedDataUser objects
 */
  public static initiateUsersFromUsers(
    { users, interactions }: { users: User[]; interactions: GroupedDataInteraction[] },
  ): GroupedDataUser[] {
    return users.map(
      (user, userIndex) => new GroupedDataUser({
        ifi: new InverseFunctionalIdentifier({ mbox: `mailto:${user.email}` }),
        userIndex,
        interactions,
      }),
    );
  }

  /**
 * Creates GroupedDataUser objects from statement objects
 *
 * @param statements - A list of Statement objects
 * @returns A set of GroupedDataUser objects
 */
  public static initiateUsersFromStatements(
    { statements, interactions }:
    { statements: Statement[]; interactions: GroupedDataInteraction[] },
  ): GroupedDataUser[] {
  // Get all unique users from the statements
    const uniqueUsers: { [key: string]: InverseFunctionalIdentifier } = {};
    statements.forEach((statement) => {
      const ifi = getInverseFunctionalIdentifier(statement);
      uniqueUsers[ifi.hash] = ifi;
    });

    // Create a GroupedDataUser object for each unique user
    return Object.values(uniqueUsers).map(
      (user, userIndex) => new GroupedDataUser({ ifi: user, userIndex, interactions }),
    );
  }
}
