import { Statement } from '../../types/statement';
import {
  VERB_URL_ANSWERED,
  VERB_URL_COMPLETED,
  VERB_URL_EXITED,
  VERB_URL_INITIALIZED,
  VERB_URL_LAUNCHED,
  VERB_URL_SCORED,
} from '../../types/verb';
import { sortStatementsDesc } from './sort';

export default class StatementVerbHelper {
  /**
     * Get a list of statements that have the exited or completed verb
     *
     * @param statements - A list of Statement objects
     * @param statementIdxs - A list of Statement indexes
     * @returns A list of Statements
     */
  public static getStatementsWithResultExtension(
    statements: Statement[],
  ): Statement[] {
    return sortStatementsDesc([
      ...this.getStatementsByExitedVerb(statements),
      ...this.getStatementsByCompletedVerb(statements),
    ]);
  }

  /**
     * Get a list of statements that have the scored or answered verb
     *
     * @param statements - A list of Statement objects
     * @param statementIdxs - A list of Statement indexes
     * @returns A list of Statements
     */
  public static getStatementsWithScoreExtension(
    statements: Statement[],
  ): Statement[] {
    return sortStatementsDesc([
      ...this.getStatementsByScoredVerb(statements),
      // ...this.getStatementsByAnsweredVerb(statements),
    ]);
  }

  /**
    * Get a list of statements filtered on the initialized verb
     *
     * @param statements - A list of Statement objects
     * @param statementIdxs - A list of Statement indexes
     * @returns A list of Statements
     */
  public static getStatementsByInitializedVerb(
    statements: Statement[],
  ): Statement[] {
    return this.getStatementsByVerb(statements, VERB_URL_INITIALIZED);
  }

  /**
    * Get a list of statements filtered on the launched verb
     *
     * @param statements - A list of Statement objects
     * @param statementIdxs - A list of Statement indexes
     * @returns A list of Statements
     */
  public static getStatementsByLaunchedVerb(
    statements: Statement[],
  ): Statement[] {
    return this.getStatementsByVerb(statements, VERB_URL_LAUNCHED);
  }

  /**
   * Get a list of statements filtered on a specific verb
   *
   * @param statements - A list of Statement objects
   * @param statementIdxs - A list of Statement indexes
   * @param verb - The verb to filter on
   * @returns A list of Statements
   */
  private static getStatementsByVerb(
    statements: Statement[],
    verb: string,
  ): Statement[] {
    return statements.filter(
      (statement) => statement.verb.id === verb,
    );
  }

  /**
   * Get a list of statements filtered on the exited verb
   *
   * @param statements - A list of Statement objects
   * @param statementIdxs - A list of Statement indexes
   * @returns A list of Statements
   */
  private static getStatementsByExitedVerb(
    statements: Statement[],
  ): Statement[] {
    return this.getStatementsByVerb(statements, VERB_URL_EXITED);
  }

  /**
   * Get a list of statements filtered on the completed verb
   *
   * @param statements - A list of Statement objects
   * @param statementIdxs - A list of Statement indexes
   * @returns A list of Statements
   */
  private static getStatementsByCompletedVerb(
    statements: Statement[],
  ): Statement[] {
    return this.getStatementsByVerb(statements, VERB_URL_COMPLETED);
  }

  /**
   * Get a list of statements filtered on the scored verb
   *
   * @param statements - A list of Statement objects
   * @param statementIdxs - A list of Statement indexes
   * @returns A list of Statements
   */
  private static getStatementsByScoredVerb(
    statements: Statement[],
  ): Statement[] {
    return this.getStatementsByVerb(statements, VERB_URL_SCORED);
  }

  /**
   * Get a list of statements filtered on the answered verb
   *
   * @param statements - A list of Statement objects
   * @param statementIdxs - A list of Statement indexes
   * @returns A list of Statements
   */
  public static getStatementsByAnsweredVerb(
    statements: Statement[],
  ): Statement[] {
    return this.getStatementsByVerb(statements, VERB_URL_ANSWERED);
  }
}
