import { DateTime } from 'luxon';

import { Statement } from '../../types/statement';

export function sortStatementsAsc(statements: Statement[]): Statement[] {
  return statements.sort(
    (a, b) => DateTime.fromISO(a.timestamp ?? a.stored).toUnixInteger()
        - DateTime.fromISO(b.timestamp ?? b.stored).toUnixInteger(),
  );
}

export function sortStatementsDesc(statements: Statement[]): Statement[] {
  return statements.sort(
    (a, b) => DateTime.fromISO(b.timestamp ?? b.stored).toUnixInteger()
        - DateTime.fromISO(a.timestamp ?? a.stored).toUnixInteger(),
  );
}
